1b\u5426\u5219\u5224\u4e3a\u53ef\u52a0/\u72ec\u7acb\u3002\n- \u5168\u90e8\u9608\u503c\u4e0e MMB \u5728\u6570\u636e\u5206\u6790\u524d\u5199\u5165\u9884\u6ce8\u518c\u8868\uff1b3 \u4e2a\u968f\u673a\u79cd\u5b50\u4f5c\u4e3a\u968f\u673a\u6548\u5e94\u5904\u7406\uff0c\u907f\u514d\u4ee5 p \u503c\u5355\u70b9\u5224\u8bfb\u3002\n\n## 2. \u4e24\u4e2a\u81ea\u53d8\u91cf\u7ef4\u5ea6\u4e0e\u6b63\u4ea4\u5316\n**\u7ef4\u5ea6 A\uff1a\u52a8\u6001\u4e0a\u4e0b\u6587\u8bb0\u5fc6\u67e5\u627e**\n- [HYP] A \u5c42\uff08\u4e3b\u5bf9\u6bd4\u7528\uff09\uff1aA1b\uff1d\u201c\u56fa\u5b9a\u9009\u62e9 top-K \u5355\u5143\u201d\uff08\u6309\u56fa\u5b9a\u6b65\u957f\u62bd\u53d6\uff0c\u65e0\u67e5\u8be2\u81ea\u9002\u5e94\uff0c\u9884\u7b97 B \u4e0e A2 \u76f8\u540c\uff09\uff1bA2\uff1d\u201cInfLLM \u5f0f\u52a8\u6001\u67e5\u627e\u201d\uff08\u6bcf\u89e3\u7801\u6b65\u7528\u5f53\u524d token \u9690\u85cf\u72b6\u6001\u5bf9\u5355\u5143\u8868\u793a\u6253\u5206\uff0c\u68c0\u7d22 top-K \u5355\u5143\u7cbe\u8bfb\u5176 KV\uff09\u3002\u4e3b\u5173\u952e\u6027\u5bf9\u6bd4\uff1dA2 \u2212 A1b\uff0c\u4e25\u683c\u540c\u9884\u7b97\uff0c\u9694\u79bb\u201c\u67e5\u8be2\u81ea\u9002\u5e94\u201d\u673a\u5236\u672c\u8eab\u3002\n- \u53c2\u7167/\u8fb9\u754c\u5c42\uff1aA0b\uff1d\u4ec5\u6700\u8fd1\u7a97\u53e3 W\uff08\u57fa\u7840\u8bbe\u65bd\u4e0b\u9650\uff09\uff1bA0a\uff1d\u5168\u5e8f\u5217\u6ce8\u610f\u529b\uff08\u7cbe\u5ea6\u4e0a\u754c\uff0c\u4ec5\u5728\u5c0f\u9884\u7b97\u957f\u5ea6\u5185\u8fd0\u884c\uff09\uff1bA1a\uff1d\u9759\u6001\u5168\u5c40\u8bb0\u5fc6\uff08\u7cbe\u8bfb\u6240\u6709\u5355\u5143\u7684\u6269\u5c55\u8868\u793a\uff0c\u6bcf\u5355\u5143\u4ec5 1 \u4e2a\u8868\u793a token\uff0c\u9884\u7b97\u968f\u5355\u5143\u6570\u53d8\u5316\uff0c\u4f5c\u6b21\u7ea7\u53c2\u7167\uff09\u3002\n- A3 \u5b9e\u73b0\u654f\u611f\u6027\uff08\u4e0d\u5728\u4e3b\u5bf9\u6bd4\uff09\uff1a\u6253\u5206\u51fd\u6570\uff08\u70b9\u79ef/\u4f59\u5f26/MLP\uff09\u3001K \u503c\uff084/8/16/32\uff09\u3001\u6e29\u5ea6\uff1b\u7528\u4e8e\u56de\u7b54\u201c\u673a\u5236\u5b9e\u73b0\u7ec6\u8282\u662f\u5426\u6539\u53d8\u7ed3\u8bba\u201d\u3002\n\n**\u7ef4\u5ea6 B\uff1a\u5355\u5143\u8868\u793a\uff08\u7c92\u5ea6\uff09**\n- [HYP] B \u6c34\u5e73\uff1atoken \u7ea7\uff08\u9000\u5316\u53c2\u7167\uff0cK=\u6bcf token\uff09\u3001\u53e5\u5b50\u7ea7\u3001\u6bb5\u843d\u7ea7\u3001\u56fa\u5b9a\u5757\uff0864/128/256 token\uff09\u3002\u8868\u793a\u5411\u91cf\u6784\u9020\u4e3a\u4e3b\u8f74\uff1b\u6b21\u7ea7\u5b50\u8f74\uff08\u5747\u503c\u6c60\u5316 vs \u672b/\u9996 token\uff1b\u662f\u5426\u53e6\u5b58\u6269\u5c55\u8868\u793a\uff09\u653e\u5728 A3 \u654f\u611f\u6027\u4e2d\uff0c\u907f\u514d\u6c61\u67d3\u4e3b\u6790\u56e0\u3002\n- [FACT] \u6b63\u4ea4\u5316\uff1a\u5168\u6790\u56e0 A\u00d7B\uff08A \u4e3b\u5c42 2 \u00d7 B 4 \u7c92\u5ea6 + \u53c2\u7167\u5c42\u4e0e A3 \u5b50\u65cb\u94ae\uff09\uff0c\u5355\u5143\u683c\u95f4\u552f\u4e00\u5dee\u5f02\u662f (A \u5c42, B \u5c42)\uff1b\u57fa\u5ea7\u6a21\u578b\u3001\u4e0a\u4e0b\u6587\u957f\u5ea6\u3001\u4efb\u52a1\u3001\u89e3\u7801\u8bbe\u7f6e\uff08\u8d2a\u5fc3\uff09\u3001\u63d0\u793a\u6a21\u677f\u3001\u79cd\u5b50\u5168\u90e8\u56fa\u5b9a\u3002\n\n## 3. \u68c0\u7d22\u9884\u7b97\u5bf9\u9f50\uff08\u6d88\u9664\u201ctop-K \u5355\u5143 vs top-K token\u201d\u7684\u6df7\u6742\uff09\n**3.1 \u4e3b\u53e3\u5f84\uff1a\u5b9e\u9645\u7cbe\u8bfb token \u6570 B\uff08\u68c0\u7d22\u5206\u652f\uff09**\n[FACT] \u5b9a\u4e49 B=\u6bcf\u4e2a\u67e5\u8be2 token \u4ece\u201c\u67e5\u627e\u5206\u652f\u201d\u5b9e\u9645\u8bfb\u53d6\u7684 KV token \u6570\uff08\u4e0d\u542b\u56fa\u5b9a\u6700\u8fd1\u7a97\u53e3 W \u4e0e\u6269\u5c55\u8868\u793a\u7684 ~N/\u5355\u5143 \u4e2a token\uff09\u3002\u4ee4 \u03bc_g=\u8be5\u7c92\u5ea6\u5e73\u5747\u5355\u5143 token \u6570\uff08token=1\uff1b\u53e5\u5b50\u224820\uff1b\u6bb5\u843d\u224880\uff1b\u5757=C\uff09\uff0c\u5219\nK_g = \u2308B / \u03bc_g\u2309\u3002\n\u4e3b\u5206\u6790\u56fa\u5b9a B\u2208{512, 2048} \u4e24\u6863\uff0c\u6240\u6709\u7c92\u5ea6\u5728\u540c\u4e00 B \u4e0b\u6bd4\u8f83\u2014\u2014\u7c92\u5ea6\u6bd4\u8f83\u4e0d\u518d\u88ab\u9884\u7b97\u7ed1\u67b6\u3002\n**3.2 \u6362\u7b97\u8868\uff08\u793a\u4f8b\uff0cB=1024\uff09**\n| \u7c92\u5ea6 | \u03bc | K=\u23081024/\u03bc\u2309 | \u8bfb\u53d6 token |\n| token | 1 | 1024 | 1024 |\n| \u53e5\u5b50 | ~20 | ~51 | ~1020 |\n| \u6bb5\u843d | ~80 | ~13 | ~1040 |\n| \u5757128 | 128 | 8 | 1024 |\n**3.3 \u654f\u611f\u6027\u5206\u6790\uff08\u8f85\u53e3\u5f84\uff09**\uff1aK \u53d6\u56fa\u5b9a\u503c\uff088/16\uff09\u65f6\u5404\u7c92\u5ea6\u8bfb\u53d6 token \u6570\u663e\u8457\u4e0d\u540c\uff08token=8\uff1b\u53e5\u5b50\u2248160\uff1b\u6bb5\u843d\u2248640\uff1b\u5757128=1024\uff09\uff0c\u6b64\u53e3\u5f84\u7528\u4e8e\u5c55\u793a\u201c\u82e5\u4e0d\u6821\u51c6\u9884\u7b97\uff0c\u7ed3\u8bba\u5982\u4f55\u88ab\u9884\u7b97\u626d\u66f2\u201d\uff0c\u5e76\u4f5c\u4e3a\u534f\u53d8\u91cf\u7eb3\u5165\u7a33\u5065\u6027\u68c0\u9a8c\u3002\n**3.4 \u5176\u4ed6\u9884\u7b97\u7ef4\u5ea6**\uff1a\u5b58\u50a8\u5f00\u9500\uff08\u6bcf\u5355\u5143 1 \u4e2a\u8868\u793a\u5411\u91cf \u2192 \u7c97\u7c92\u5ea6\u66f4\u7701\uff09\u3001\u6bcf\u6b65\u6253\u5206\u6210\u672c\uff08\u6253\u5206\u5355\u5143\u6570=N/\u03bc_g\uff0c\u7c97\u7c92\u5ea6\u66f4\u4f4e\uff09\u4ee5\u65f6\u5ef6/\u663e\u5b58\u6307\u6807\u5355\u72ec\u62a5\u544a\uff0c\u4e0d\u4e0e\u51c6\u786e\u7387\u6df7\u5408\u5224\u5b9a\u5173\u952e\u6027\u3002\n\n## 4. \u4efb\u52a1\u3001\u6570\u636e\u96c6\u4e0e\u56e0\u53d8\u91cf\n- \u5408\u6210\u53ef\u63a7\uff1aneedle-in-a-haystack\uff08\u6df1\u5ea6 5%\u201395% \u00d7 \u957f\u5ea6 8k/16k/32k/64k\uff09\u3001passkey\u3001RULER multi-needle\u2014\u2014\u63d0\u4f9b\u201c\u68c0\u7d22\u547d\u4e2d\u7387\u201d\u8fd9\u4e00\u673a\u5236\u53d8\u91cf\uff08\u6b63\u786e\u5355\u5143\u8fdb\u5165 top-K \u7684\u6bd4\u4f8b\uff09\u3002\n- [FACT] \u771f\u5b9e\u57fa\u51c6\uff08[TBD] \u83b7\u53d6\u4e0e\u8bb8\u53ef\uff09\uff1aLongBench \u5b50\u96c6\uff08Qasper\u3001MultiFieldQA\u3001HotpotQA\u30012WikiMultihopQA\u3001GovReport\u3001QMSum\u3001TREC\u3001TriviaQA\u3001LCC\u3001RepoBench-P\uff09\uff1bRULER/LongBench-v2 \u7528\u4e8e\u66f4\u957f\u4e0a\u4e0b\u4e0e\u5916\u63a8\u5ea6\u91cf\uff1b\u56f0\u60d1\u5ea6\u7528 PG-19 \u6216 WikiText-103 \u7559\u5b58\u6bb5\u3002\n- \u56e0\u53d8\u91cf\uff1a\u4efb\u52a1\u51c6\u786e\u7387\u3001\u68c0\u7d22\u547d\u4e2d\u7387\u3001\u56f0\u60d1\u5ea6\u3001\u65f6\u5ef6\uff08ms/token\uff09\u3001\u5cf0\u503c\u663e\u5b58\u3001\u6bcf\u5355\u5143\u6253\u5206\u6570\u3001\u5916\u63a8\u7ef4\u6301\u5ea6\uff08\u8d85\u51fa\u8bad\u7ec3\u7a97\u53e3\u7684\u51c6\u786e\u7387\uff09\u3002\n- \u63a7\u5236\u9879\uff1a\u8d2a\u5fc3\u89e3\u7801\uff1b\u76f8\u540c\u63d0\u793a\u6a21\u677f\uff1b\u56fa\u5b9a\u957f\u5ea6\u7f51\u683c\uff1b\u56fa\u5b9a\u6837\u672c\u6570\uff1b3 \u79cd\u5b50\u91cd\u590d\u62a5\u544a\u5747\u503c\u00b1SD \u4e0e bootstrap CI\u3002\n\n## 5. \u5916\u90e8\u57fa\u7ebf\u4e0e\u6d88\u878d\n- [FACT] \u5916\u90e8\u57fa\u7ebf\uff1aFullKV\uff08\u53ef\u884c\u957f\u5ea6\u5185\uff09\u3001StreamingLLM\u3001H2O\u3001\u6700\u8fd1\u7a97\u53e3\u2014\u2014\u7f6e\u4e8e\u53c2\u7167\u5c42\uff0c\u4e0d\u8fdb\u4e3b\u5bf9\u6bd4\u3002\n- \u6d88\u878d\uff1aA2 \u53bb\u6389\u6269\u5c55\u8868\u793a\u53ea\u7559 top-K \u5757\uff1b\u4e0d\u540c K\uff1b\u4e0d\u540c\u6253\u5206\u51fd\u6570\uff1b\u4e0d\u540c\u5757\u5927\u5c0f\uff1b\u4e0d\u540c\u8868\u793a\u6784\u9020\u2014\u2014\u5168\u90e8\u5f52\u5165 A3/\u6b21\u7ea7\u8f74\u505a\u654f\u611f\u6027\uff0c\u4e3b\u7ed3\u8bba\u53ea\u4f9d\u636e\u4e3b\u6790\u56e0\u683c\u3002\n\n## 6. \u5206\u5c42\u4ea4\u4ed8\uff1aT1/T2/T3 \u7684\u5fc5\u8981\u5355\u5143\u683c\u3001\u6837\u672c\u3001\u79cd\u5b50\u4e0e\u9884\u7b97\n**T1\uff08\u6700\u5c0f\u53ef\u56de\u7b54\u95ee\u9898\u7684\u6700\u5c0f\u914d\u7f6e\uff0cpilot\uff09**\uff1a\u56de\u7b54\u201c\u52a8\u6001\u67e5\u627e\u662f\u5426\u5173\u952e\u3001\u7c92\u5ea6\u662f\u5426\u5173\u952e\u3001\u662f\u5426\u76f8\u4e92\u4f9d\u8d56\u201d\u2014\u20145\u20136 \u5355\u5143\u683c\uff1a{A1b, A2} \u00d7 {\u53e5\u5b50, \u5757128} + A0b \u53c2\u7167\uff08+A0a \u77ed\u957f\u5ea6\u4e0a\u754c\uff09\u3002\u5355\u4efb\u52a1\uff08NIAH 8